import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AccessibilityInfo, AppState, Image, PanResponder, Platform, View, type AccessibilityActionEvent } from 'react-native';
import { EARTH_FRAMES } from './earthFrames';

// Photographic globe: offline raycast renders of NASA Blue Marble. Individual 128px frames
// (generated by scripts/split-earth-frames.js from assets/earth/globe_t*.jpg atlases).
// 9 tilts (lat -60..60 step 15) x 72 longitudes (0..355 step 5). See assets/earth/ATTRIBUTION.txt.
const STEP = 5, FRAMES = 72;
const FALLBACK = require('@/assets/images/earth-logo.png');
let loggedFailure = false;

export function EarthGlobe({ size }: { size: number }) {
  // Start on the Americas (lon -75 -> frame 57).
  const [rot, setRot] = useState({ lon: -75, lat: 12 });
  const rotRef = useRef(rot);
  rotRef.current = rot;
  const dragging = useRef(false);
  const [reduceMotion, setReduceMotion] = useState(false);
  const [active, setActive] = useState(AppState.currentState === 'active');
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion).catch(() => {});
    const a = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduceMotion);
    const b = AppState.addEventListener('change', (s) => setActive(s === 'active'));
    return () => { a.remove(); b.remove(); };
  }, []);

  // Auto-rotation: advance one 5° frame per second. Paused while dragging, backgrounded, or reduced motion.
  useEffect(() => {
    if (reduceMotion || !active) return;
    const id = setInterval(() => {
      if (!dragging.current) setRot((r) => ({ lon: (r.lon + STEP) % 360, lat: r.lat }));
    }, 1000);
    return () => clearInterval(id);
  }, [reduceMotion, active]);

  const pan = useMemo(() => {
    let start = { lon: 0, lat: 0 };
    return PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderTerminationRequest: () => false,
      onPanResponderGrant: () => { dragging.current = true; start = rotRef.current; },
      onPanResponderMove: (_e, g) => {
        const k = 180 / Math.max(size, 30);
        setRot({ lon: start.lon - g.dx * k, lat: Math.max(-60, Math.min(60, start.lat + g.dy * k)) });
      },
      onPanResponderRelease: () => { dragging.current = false; },
      onPanResponderTerminate: () => { dragging.current = false; },
    });
  }, [size]);

  const onAction = (e: AccessibilityActionEvent) => {
    const step = e.nativeEvent.actionName === 'increment' ? 30 : e.nativeEvent.actionName === 'decrement' ? -30 : 0;
    if (step) setRot((r) => ({ ...r, lon: r.lon - step }));
  };

  const idx = Math.round((((rot.lon % 360) + 360) % 360) / STEP) % FRAMES;
  const tilt = Math.max(0, Math.min(8, Math.round((rot.lat + 60) / 15)));
  const source = failed ? FALLBACK : EARTH_FRAMES[tilt][idx];
  const slop = Math.max(0, (44 - size) / 2);

  return (
    <View
      {...pan.panHandlers}
      hitSlop={{ top: slop, bottom: slop, left: slop, right: slop }}
      accessible
      accessibilityRole="adjustable"
      accessibilityLabel="Earth globe"
      accessibilityHint="Drag to rotate the globe"
      accessibilityActions={[{ name: 'increment', label: 'Rotate east' }, { name: 'decrement', label: 'Rotate west' }]}
      onAccessibilityAction={onAction}
      style={[{ width: size, height: size }, Platform.OS === 'web' ? ({ touchAction: 'none', cursor: 'grab' } as object) : null]}
    >
      <View pointerEvents="none" style={{ width: size, height: size, borderRadius: size / 2, overflow: 'hidden', backgroundColor: '#0B3A66' }}>
        {/* Single persistent Image; only its source changes. Ocean-blue backdrop keeps the globe visible while loading. */}
        <Image
          source={source}
          fadeDuration={0}
          resizeMode="contain"
          style={{ width: size, height: size }}
          onError={(e) => {
            if (!loggedFailure) { loggedFailure = true; console.warn('[EarthGlobe] frame failed to load, using fallback', e.nativeEvent?.error); }
            if (!failed) setFailed(true);
          }}
        />
      </View>
    </View>
  );
}
